+// Aborts the request when the caller's signal aborts. The listener is detached
+// once the request reaches a terminal status, since abort() is a no-op from
+// that point on. Without detaching, the listener keeps the whole Request
+// reachable for as long as the caller's signal lives, and a composite signal
+// from AbortSignal.any() is itself retained by the runtime while it has any
+// abort listener attached.
+//
+// A request whose stream is never consumed does not reach a terminal status, so
+// its listener stays attached for as long as the caller's signal lives.
+export function attachAbortSignal(request: Request, signal: AbortSignal): void {
+  if (signal.aborted) {
+    abort(request, signal.reason);
+    return;
+  }
+  function listener() {
+    detach();
+    abort(request, signal.reason);
+  }
+  function detach() {
+    request.detachAbortSignal = null;
+    signal.removeEventListener('abort', listener);
+  }
+  request.detachAbortSignal = detach;
+  signal.addEventListener('abort', listener);

